bank=[]
def mcq(group, text):
    for i,line in enumerate(text.strip().splitlines(),1):
        q,a,b,c,d,why,source,topic=line.split('|')
        bank.append(dict(id=f'{group}-m{i:02}',type='mcq',group=group,prompt=q,options=[a,b,c,d],correct=0,explanation=why,source=source,topic=topic))
def short(group,text):
    for i,line in enumerate(text.strip().splitlines(),1):
        q,a,b,source,topic=line.split('|')
        bank.append(dict(id=f'{group}-s{i:02}',type='short',group=group,prompt=q,answer=[a,b],source=source,topic=topic))

